    Props (p): p, labels, ratio. *}
{var $v_p = ($p['p'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_ratio = ($p['ratio'] ?? '4/3')}
{capture $c_8}
  {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => ui_get($v_p, ['title']), 'ratio' => $v_ratio, 'className' => ui_cnv([(ui_t(ui_eq($v_ratio, '4/3')) ? 'min-h-80' : 'min-h-64')])]])|noescape}
  {capture $c_7}
    {capture $c_3}
      {capture $c_1}
        {=ui_text(ui_get($v_p, ['category']))}
      {/capture}
      {=ui_include('ui/badge/badge.latte', ['p' => ['Variant' => 'secondary', 'Size' => 'sm'], 'children' => $c_1])|noescape}
      {capture $c_2}
        {=ui_text(ui_get($v_p, ['date']))}
      {/capture}
      {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xs', 'Class' => 'text-muted-foreground'], 'children' => $c_2])|noescape}
    {/capture}
    {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '2', 'Align' => 'center'], 'children' => $c_3])|noescape}
    {capture $c_4}
      {=ui_text(ui_get($v_p, ['title']))}
    {/capture}
    {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(3), 'Size' => 'base', 'Weight' => 'semibold'], 'children' => $c_4])|noescape}
    {capture $c_5}
      {=ui_text(ui_get($v_p, ['excerpt']))}
    {/capture}
